static inline ktime_t timespec64_to_ktime(struct timespec64 ts) /* <=== timespec64_to_ktime */ 
{
	return ktime_set(ts.tv_sec, ts.tv_nsec);
}

static inline ktime_t ktime_set(const s64 secs, const unsigned long nsecs) /* <=== ktime_set */ 
{
	if (unlikely(secs >= KTIME_SEC_MAX))
		return KTIME_MAX;

	return secs * NSEC_PER_SEC + (s64)nsecs;
}

